(4439354, 638684, 51538, '<td valign="top">Well framed. Nice intimate view.  Symbolic really. 8.</td>', 'Well framed. Nice intimate view.  Symbolic really. 8.', '2008-01-30 10:15:30.000000', NULL, 1),
(4439366, 638987, 51538, '<td valign="top">It''s hard to deny a fascination of this tiny frozen moment in time.  It looks naturally unnatural, so to speak.</td>', 'It''s hard to deny a fascination of this tiny frozen moment in time.  It looks naturally unnatural, so to speak.', '2008-01-30 10:17:31.000000', NULL, 1),
