(4439515, 639030, 33352, '<td valign="top">Nice silhouette, good background color for the contrast.</td>', 'Nice silhouette, good background color for the contrast.', '2008-01-30 10:38:41.000000', NULL, 1),
(4439519, 638901, 69368, '<td valign="top">oh, this is wonderful! Nice DOF, great details</td>', 'oh, this is wonderful! Nice DOF, great details', '2008-01-30 10:39:41.000000', NULL, 1),
(4439520, 638776, 33352, '<td valign="top">Trying to create a contrast has lost the impact.</td>', 'Trying to create a contrast has lost the impact.', '2008-01-30 10:39:42.000000', NULL, 1),
