(4439533, 637589, 33352, '<td valign="top">Busy background.</td>', 'Busy background.', '2008-01-30 10:41:20.000000', NULL, 1),
(4439538, 638541, 33352, '<td valign="top">good lighting on subject,</td>', 'good lighting on subject,', '2008-01-30 10:42:19.000000', NULL, 1),
(4439550, 636871, 33352, '<td valign="top">well put together and should be higher than I believe DPC will score it.</td>', 'well put together and should be higher than I believe DPC will score it.', '2008-01-30 10:43:41.000000', NULL, 1),
(4439551, 638969, 33352, '<td valign="top">Busy foreground...</td>', 'Busy foreground...', '2008-01-30 10:44:08.000000', NULL, 1),
