(4442781, 638916, 88010, '<td valign="top">If this were a bit more crisp and popped with sharpness this would be National Geographic material. Nice capture, just not sharp.</td>', 'If this were a bit more crisp and popped with sharpness this would be National Geographic material. Nice capture, just not sharp.', '2008-01-31 08:48:38.000000', NULL, 1),
(4442785, 638455, 88010, '<td valign="top">Very noisy, grainy. Otherwise a nice tranquil shot.</td>', 'Very noisy, grainy. Otherwise a nice tranquil shot.', '2008-01-31 08:49:10.000000', NULL, 1),
(4442787, 638076, 88010, '<td valign="top">Not quite sharp at the eyes, and the eyes need to pop with sharpness. But a nice capture other than that.</td>', 'Not quite sharp at the eyes, and the eyes need to pop with sharpness. But a nice capture other than that.', '2008-01-31 08:49:47.000000', NULL, 1),
