(4442792, 638680, 88010, '<td valign="top">Very soft. Also very small in the frame.</td>', 'Very soft. Also very small in the frame.', '2008-01-31 08:51:01.000000', NULL, 1),
(4442794, 638492, 88880, '<td valign="top">Nice!  Great capture!</td>', 'Nice!  Great capture!', '2008-01-31 08:51:39.000000', NULL, 1),
(4442795, 638987, 88010, '<td valign="top">Very nice, a little noisy but other than that this is awesome. colors, contrast, composition are all good. Just too much grain.</td>', 'Very nice, a little noisy but other than that this is awesome. colors, contrast, composition are all good. Just too much grain.', '2008-01-31 08:51:50.000000', NULL, 1),
