(4444360, 638862, 45524, '<td valign="top">Nice color combination and background.</td>', 'Nice color combination and background.', '2008-01-31 19:14:38.000000', NULL, 1),
(4444362, 638673, 45524, '<td valign="top">Great detail and focus. I like this shot. 8</td>', 'Great detail and focus. I like this shot. 8', '2008-01-31 19:15:20.000000', NULL, 1),
