(4447252, 639049, 66952, '<td valign="top">Beautiful. Perfect. The natural landscape, the line of birds fading into the distance, the square crop, and the excellent b&amp;w conversion all work together perfectly. 10.</td>', 'Beautiful. Perfect. The natural landscape, the line of birds fading into the distance, the square crop, and the excellent b&w conversion all work together perfectly. 10.', '2008-02-01 14:55:54.000000', NULL, 1),
(4447253, 638915, 4162, '<td valign="top">A great capture-love the hair!</td>', 'A great capture-love the hair!', '2008-02-01 14:56:21.000000', NULL, 1),
