(4450470, 638541, 75651, '<td valign="top">Beautiful photograph.  Muted background, great focus.  GReat job!</td>', 'Beautiful photograph.  Muted background, great focus.  GReat job!', '2008-02-02 12:15:02.000000', NULL, 1),
(4450476, 638707, 88010, '<td valign="top">Yes they are quite colorful. Good job on the focus, colors, and saturation. Contrast could be boosted a hair. Composition makes me feel like he''s falling over.</td>', 'Yes they are quite colorful. Good job on the focus, colors, and saturation. Contrast could be boosted a hair. Composition makes me feel like he''s falling over.', '2008-02-02 12:15:34.000000', NULL, 1),
(4450480, 638666, 88010, '<td valign="top">You need fill flash, we''ve lost all detail in the shadows, which is most of the bird. also very fuzzy, probably from a huge crop or camera movement from not using a tripod.</td>', 'You need fill flash, we''ve lost all detail in the shadows, which is most of the bird. also very fuzzy, probably from a huge crop or camera movement from not using a tripod.', '2008-02-02 12:16:36.000000', NULL, 1),
(4450486, 638025, 88010, '<td valign="top">cute little fellow, nice focus on the eyes. composition is not pleasing as he is too left of center which makes it feel as though he is leaving the frame of the photo. he needs to be entering the framework. colors, contrast and saturation all very nice.</td>', 'cute little fellow, nice focus on the eyes. composition is not pleasing as he is too left of center which makes it feel as though he is leaving the frame of the photo. he needs to be entering the framework. colors, contrast and saturation all very nice.', '2008-02-02 12:17:54.000000', NULL, 1),
