(4454851, 638039, 22970, '<td valign="top">Not a bad photograph but at the same time not interesting. Your focus is good and lighting. Shadows across the subject are distracting. Wish you the best in this challenge and future challenges.</td>', 'Not a bad photograph but at the same time not interesting. Your focus is good and lighting. Shadows across the subject are distracting. Wish you the best in this challenge and future challenges.', '2008-02-03 19:42:11.000000', NULL, 1),
(4454855, 638869, 22970, '<td valign="top">Nice focus and great broken background.</td>', 'Nice focus and great broken background.', '2008-02-03 19:43:33.000000', NULL, 1),
(4454863, 636450, 22970, '<td valign="top">Very nice photograph. The lighting, focus, colors, and DOF are great. A gorgeous Cardinal. Bump</td>', 'Very nice photograph. The lighting, focus, colors, and DOF are great. A gorgeous Cardinal. Bump', '2008-02-03 19:46:11.000000', NULL, 1),
(4454871, 638987, 32848, '<td valign="top">One of the top shots in the challenge. Lovely capture, you''ve stopped the motion completely, no mean feat with a humming bird. Well done.</td>', 'One of the top shots in the challenge. Lovely capture, you''ve stopped the motion completely, no mean feat with a humming bird. Well done.', '2008-02-03 19:52:13.000000', NULL, 1),
(4454875, 637564, 32848, '<td valign="top">Great capture of a mallard taking flight. Timing was very good as you don''t tend to get much warning, they just "explode"! Great background and love the droplets...</td>', 'Great capture of a mallard taking flight. Timing was very good as you don''t tend to get much warning, they just "explode"! Great background and love the droplets...', '2008-02-03 19:53:21.000000', NULL, 1),
(4454879, 638135, 32848, '<td valign="top">Nice shot of the bird in the snow. DOF a bit tight, but it''s always a problem with small subjects and big focal lengths!</td>', 'Nice shot of the bird in the snow. DOF a bit tight, but it''s always a problem with small subjects and big focal lengths!', '2008-02-03 19:54:15.000000', NULL, 1);
